// 1. SLABA ENKAPSULACJA - 'public' oznaczalo widoczne dla DOSLOWNIE kazdego na classpath,
//    biblioteki mogly tylko UMOWIC SIE PRZEZ KONWENCJE (np. pakiet .internal), bez realnej ochrony.
// 2. NIEPEWNA KONFIGURACJA - brakujaca zaleznosc ujawniala sie dopiero w RUNTIME
//    (NoClassDefFoundError), a nie przy starcie aplikacji.
// 3. MONOLITYCZNY JDK - samo srodowisko uruchomieniowe bylo jednym, gigantycznym blokiem,
//    nie dalo sie dostarczyc 'malej' Javy bez nieuzywanych modulow AWT/Swing/CORBA.

// module-info.java:
// module com.example.orders {
//     requires com.example.customers;
//     exports com.example.orders.api;
// }

// requires X: modul deklaruje, ze SAM POTRZEBUJE modulu X, zeby dzialac (zarowno przy
// kompilacji, jak i w runtime). Buduje to graf czytelnosci - modul deklarujacy requires
// 'czyta' modul wymieniony po requires, moze uzywac jego eksportowanych typow.
// exports Y: modul deklaruje, ze jego WLASNY pakiet Y jest czescia publicznego API,
// widocznego dla KAZDEGO modulu, ktory ten modul 'requires'. Bez exports, pakiet (nawet
// z publicznymi klasami) jest silnie ukryty - niewidoczny spoza wlasnego modulu.

// Modul nienazwany (unnamed module) to specjalny, 'domyslny' modul, do ktorego trafiaja
// WSZYSTKIE klasy uruchamiane na klasycznym CLASSPATH (opcja -cp), zamiast na module-path.
// Czyta kazdy inny modul w systemie i eksportuje WSZYSTKIE swoje pakiety kazdemu - dziala
// dokladnie jak classpath sprzed Javy 9, bez zadnej silnej enkapsulacji.
// javaQuest w nim dziala, bo CALY projekt (i mvnw.cmd) kompiluje sie i uruchamia BEZ
// module-info.java - to zapewnia PELNA wsteczna kompatybilnosc z tysiacami klas kursu.

// Modul automatyczny to JAR BEZ wlasnego module-info.class, ktory trafia na MODULE PATH
// (nie classpath) - JVM automatycznie tworzy dla niego prowizoryczny modul.
// Nazwa modulu bierze sie z DWOCH mozliwych zrodel: (1) atrybut 'Automatic-Module-Name' w
// manifescie JAR-a (jesli obecny, ma pierwszenstwo), (2) w przeciwnym razie - wyprowadzona
// automatycznie z NAZWY PLIKU JAR (np. 'gson-2.10.1.jar' -> modul 'gson').
// Widocznosc pakietow: modul automatyczny EKSPORTUJE WSZYSTKIE swoje pakiety, bez zadnej
// silnej enkapsulacji - dokladnie jak modul nienazwany.

Path workDir = Files.createTempDirectory("ex07");
Path modDir = workDir.resolve("src").resolve("hello.world");
Files.createDirectories(modDir.resolve("hello"));
Files.writeString(modDir.resolve("module-info.java"), "module hello.world {\n}\n");
Files.writeString(modDir.resolve("hello").resolve("Main.java"),
    "package hello;\npublic class Main {\n    public static void main(String[] args) { System.out.println(\"Witaj z modulu!\"); }\n}\n");
System.out.println("Katalog: " + workDir);

String javacExe = System.getProperty("java.home") + File.separator + "bin" + File.separator + "javac";
List<String> command = List.of(javacExe, "--module-source-path", srcDir.toString(),
    "-d", outDir.toString(), "--module", "hello.world");
System.out.println(String.join(" ", command));

ProcessBuilder pb = new ProcessBuilder(javacExe, "--module-source-path", srcDir.toString(), "-d", outDir.toString(), "--module", "hello.world");
pb.redirectErrorStream(true);
Process p = pb.start();
System.out.println(new String(p.getInputStream().readAllBytes()));
int exit = p.waitFor();
System.out.println("Kod wyjscia: " + exit);
System.out.println("module-info.class istnieje: " + Files.exists(outDir.resolve("hello.world").resolve("module-info.class")));

String javaExe = System.getProperty("java.home") + File.separator + "bin" + File.separator + "java";
ProcessBuilder pb = new ProcessBuilder(javaExe, "--module-path", outDir.toString(), "--module", "hello.world/hello.Main");
pb.redirectErrorStream(true);
Process p = pb.start();
System.out.println(new String(p.getInputStream().readAllBytes()));
System.out.println("Kod wyjscia: " + p.waitFor());

try (Stream<Path> walk = Files.walk(workDir)) {
    walk.sorted(Comparator.reverseOrder()).forEach(path -> { try { Files.delete(path); } catch (Exception e) { } });
}

