long t1 = System.nanoTime();
runProcess("kompilacja 1", javacExe, "--module-source-path", srcDir.toString(), "-d", out1.toString(), "--module", "shapes.api,shapes.app");
long time1 = System.nanoTime() - t1;

long t2 = System.nanoTime();
runProcess("kompilacja 2", javacExe, "--module-source-path", srcDir.toString(), "-d", out2.toString(), "--module", "shapes.api,shapes.app");
long time2 = System.nanoTime() - t2;

System.out.println("Czas 1: " + time1 / 1_000_000 + " ms, Czas 2: " + time2 / 1_000_000 + " ms");

ProcessBuilder pb = new ProcessBuilder(javaExe, "--module-path", outDir.toString(), "--describe-module", "hello.world");
pb.redirectErrorStream(true);
Process p = pb.start();
System.out.println(new String(p.getInputStream().readAllBytes()));
p.waitFor();

static String generateModuleInfo(String moduleName, List<String> requiresModules, List<String> exportsPackages) {
    StringBuilder sb = new StringBuilder("module " + moduleName + " {\n");
    for (String r : requiresModules) sb.append("    requires ").append(r).append(";\n");
    for (String e : exportsPackages) sb.append("    exports ").append(e).append(";\n");
    sb.append("}\n");
    return sb.toString();
}

System.out.println(generateModuleInfo("com.example.orders", List.of("com.example.customers"), List.of("com.example.orders.api")));
System.out.println(generateModuleInfo("hello.world", List.of(), List.of("hello")));

